def build_table(keys, size):
    table = [None] * size
    for key in keys:
        for step in range(size):
            pos = (key + step) % size
            if table[pos] == key:
                break
            if table[pos] is None:
                table[pos] = key
                break
        else:
            raise ValueError('Table full')
    return table
